-- 0078 適用後チェック（SELECT1文・読み取り専用）
with r(ord, level, item, detail) as (values
 (1, case when (select md5(prosrc) from pg_proc where oid = to_regprocedure('public.save_core_type_result(uuid)')) = 'ae6160867fd1cb88fd2cbb61c67dcb30' then 'PASS' else 'FAIL' end, 'save_core_type_result が 0078 の定義になった', coalesce((select md5(prosrc) from pg_proc where oid = to_regprocedure('public.save_core_type_result(uuid)')), '(関数なし)')),
 (2, case when has_function_privilege('authenticated', to_regprocedure('public.save_core_type_result(uuid)'), 'execute') and not has_function_privilege('anon', to_regprocedure('public.save_core_type_result(uuid)'), 'execute') and not has_function_privilege('public', to_regprocedure('public.save_core_type_result(uuid)'), 'execute') then 'PASS' else 'FAIL' end, '権限は変わらない（authenticated のみ実行できる）', ''),
 (3, case when (select prosrc from pg_proc where oid = to_regprocedure('public.save_core_type_result(uuid)')) like '%array_position(v_order%' then 'PASS' else 'FAIL' end, '1位・2位の両方に同点時の順序が入っている', ''),
 (4, case when (select code from (values ('shimei_jishaku',50),('aisare_ace',50),('niaiwase_master',50),('trend_maker',50),('iyashi_charisma',50),('repeat_king',50),('mirai_no_ace',50),('brand_builder',50)) as v(code,score) order by score desc, array_position(array['shimei_jishaku','aisare_ace','niaiwase_master','trend_maker','iyashi_charisma','repeat_king','mirai_no_ace','brand_builder'], code) asc limit 1) = 'shimei_jishaku' and (select code from (values ('shimei_jishaku',50),('aisare_ace',50),('niaiwase_master',50),('trend_maker',50),('iyashi_charisma',50),('repeat_king',50),('mirai_no_ace',50),('brand_builder',50)) as v(code,score) where code <> 'shimei_jishaku' order by score desc, array_position(array['shimei_jishaku','aisare_ace','niaiwase_master','trend_maker','iyashi_charisma','repeat_king','mirai_no_ace','brand_builder'], code) asc limit 1) = 'aisare_ace' then 'PASS' else 'FAIL' end, '同点の並べ替え（関数と同じ式・リテラルで確認）: 8タイプすべて同点', '1位 shimei_jishaku / 2位 aisare_ace'),
 (5, case when (select code from (values ('shimei_jishaku',10),('aisare_ace',20),('niaiwase_master',30),('trend_maker',30),('iyashi_charisma',30),('repeat_king',5),('mirai_no_ace',30),('brand_builder',0)) as v(code,score) order by score desc, array_position(array['shimei_jishaku','aisare_ace','niaiwase_master','trend_maker','iyashi_charisma','repeat_king','mirai_no_ace','brand_builder'], code) asc limit 1) = 'niaiwase_master' and (select code from (values ('shimei_jishaku',10),('aisare_ace',20),('niaiwase_master',30),('trend_maker',30),('iyashi_charisma',30),('repeat_king',5),('mirai_no_ace',30),('brand_builder',0)) as v(code,score) where code <> 'niaiwase_master' order by score desc, array_position(array['shimei_jishaku','aisare_ace','niaiwase_master','trend_maker','iyashi_charisma','repeat_king','mirai_no_ace','brand_builder'], code) asc limit 1) = 'trend_maker' then 'PASS' else 'FAIL' end, '同点の並べ替え（関数と同じ式・リテラルで確認）: 定義順で後ろの同点（3位以下の同点も、定義順）', '1位 niaiwase_master / 2位 trend_maker'),
 (6, 'INFO', '履歴の件数 / 1位が同点だった履歴 / 初回確定の件数（適用前チェックの値と同じ。履歴の最新行は適用後の保存で増えてよい）', (select count(*)::text||' / '||count(*) filter (where score_gap = 0)::text from public.stylist_core_type_history)||' / '||(select count(*)::text from public.stylist_core_type_assignments)),
 (7, 'INFO', '履歴の内容のハッシュ（適用前チェックの値と同じなら、保存済みの履歴は無変更。適用後に新しい診断が保存された場合は変わる）', (select coalesce(md5(string_agg(id::text||'|'||user_id::text||'|'||diagnosis_result_id::text||'|'||top_type_code::text||'|'||second_type_code::text||'|'||score_gap::text||'|'||match_scores::text||'|'||created_at::text, ',' order by id)),'(none)') from public.stylist_core_type_history)),
 (8, 'INFO', '初回確定の内容のハッシュ（適用前チェックの値と同じなら、初回確定は無変更。適用後に新規会員が確定した場合は変わる）', (select coalesce(md5(string_agg(user_id::text||'|'||core_type_code::text||'|'||source_diagnosis_result_id::text||'|'||assignment_method||'|'||assigned_at::text, ',' order by user_id)),'(none)') from public.stylist_core_type_assignments))
)
select ord, level, item, detail from (select ord::text as ord, level, item, detail from r
union all
select '99', case when (select count(*) from r where level='FAIL')=0 then 'PASS' else 'FAIL' end, '総合判定（INFO '||(select count(*) from r where level='INFO')||'件は人が確認）', 'FAIL '||(select count(*) from r where level='FAIL')||'件'
) t order by ord::int;
